-- Persistent conversations shared by the website and the desktop app.
-- Ids are generated by the client (uuid) so a retried create or append is idempotent.
-- Conversations are soft-deleted (deleted_at) so the other device learns about the delete on its next pull.
CREATE TABLE conversations (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title text NOT NULL DEFAULT '' CHECK (length(title) <= 200),
  summary text NOT NULL DEFAULT '' CHECK (length(summary) <= 4000),
  source text NOT NULL DEFAULT 'web' CHECK (source IN ('web', 'desktop')),
  created_at timestamptz NOT NULL DEFAULT now(),
  -- Last edit as reported by the editing client (clamped to server time); decides title/summary conflicts.
  edited_at timestamptz NOT NULL DEFAULT now(),
  -- Server time of the last change of any kind; the sync cursor reads this.
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);
CREATE INDEX conversations_user_list_idx ON conversations(user_id, updated_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX conversations_user_sync_idx ON conversations(user_id, updated_at);

-- Append-only. seq is the display order inside a conversation.
CREATE TABLE messages (
  id uuid PRIMARY KEY,
  conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  seq bigserial NOT NULL,
  role text NOT NULL CHECK (role IN ('user', 'assistant', 'transcript', 'screen')),
  content text NOT NULL CHECK (length(content) <= 100000),
  meta jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX messages_conversation_idx ON messages(conversation_id, seq);
CREATE INDEX messages_user_sync_idx ON messages(user_id, updated_at);

-- Model preference and response mode, shared by both clients. Constant default: metadata-only.
ALTER TABLE users ADD COLUMN settings jsonb NOT NULL DEFAULT '{}';
ALTER TABLE users ADD COLUMN settings_updated_at timestamptz NOT NULL DEFAULT now();
